package net.civeira.phylax.feature.observe.observedalertrule.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.observedalertrule.domain.ObservedAlertRule;
import net.civeira.phylax.feature.observe.observedalertrule.domain.event.ObservedAlertRuleEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ObservedAlertRuleEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ObservedAlertRuleEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final ObservedAlertRule entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
